/** Подсказки для экрана: «как изучать» эпоху и с чего начать автора. */
export const ERA_HOW = new Map(SECTIONS.flatMap((s) => s.eras.map((e) => [`${s.name}|${e.name}`, e.how])));
export const AUTHOR_TIP = new Map(SECTIONS.flatMap((s) => s.eras.flatMap((e) => e.authors.filter((x) => x.tip).map((x) => [`${s.name}|${e.name}|${x.name}`, x.tip]))));
